IF DB_ID(N'QL_TraSua') IS NULL CREATE DATABASE [QL_TraSua];
GO
USE [QL_TraSua];
CREATE TABLE dbo.DanhMucMon(MaDM int IDENTITY PRIMARY KEY,TenDM nvarchar(50) NOT NULL); CREATE TABLE dbo.MonUong(MaMon int IDENTITY PRIMARY KEY,TenMon nvarchar(100) NOT NULL,GiaBan decimal(18,0) NOT NULL,DangBan bit NOT NULL,MaDM int NOT NULL REFERENCES dbo.DanhMucMon(MaDM)); CREATE TABLE dbo.HoaDon(MaHD int IDENTITY PRIMARY KEY,NgayLap datetime NOT NULL,TongTien decimal(18,0) NOT NULL,HinhThucTT nvarchar(20) NOT NULL,DaThanhToan bit NOT NULL); CREATE TABLE dbo.ChiTietHoaDon(MaHD int NOT NULL REFERENCES dbo.HoaDon(MaHD),MaMon int NOT NULL REFERENCES dbo.MonUong(MaMon),SoLy int NOT NULL,DonGia decimal(18,0) NOT NULL,CONSTRAINT PK_ChiTiet PRIMARY KEY(MaHD,MaMon)); INSERT dbo.DanhMucMon VALUES(N'Trà sữa'),(N'Trà trái cây'),(N'Topping'),(N'Đồ ăn vặt'); INSERT dbo.MonUong VALUES(N'Trà sữa truyền thống',30000,1,1),(N'Trà sữa matcha',35000,1,1),(N'Trà sữa socola',35000,1,1),(N'Trà sữa khoai môn',38000,1,1),(N'Trà đào cam sả',32000,1,2),(N'Trà vải',30000,1,2),(N'Trà chanh',20000,1,2),(N'Trà dâu',33000,1,2),(N'Trân châu đen',7000,1,3),(N'Trân châu trắng',8000,1,3),(N'Pudding trứng',9000,1,3),(N'Khoai tây chiên',25000,1,4);

